{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Earnings Prep Data",
    "operation": "add",
    "url": "http://localhost:7805",
    "widgets_json": {
      "estimate_revisions": {
        "name": "Estimate Revisions",
        "description": "Street estimate revisions by quarter.",
        "endpoint": "/estimate-revisions",
        "type": "table",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "columnsDefs": [
            {
              "field": "quarter",
              "headerName": "Quarter",
              "cellDataType": "text"
            },
            {
              "field": "eps_estimate",
              "headerName": "EPS Est",
              "cellDataType": "number"
            },
            {
              "field": "revenue_estimate_b",
              "headerName": "Revenue Est ($B)",
              "cellDataType": "number"
            }
          ]
        }
      },
      "earnings_chart": {
        "name": "EPS History",
        "description": "Plotly EPS beat/miss history.",
        "endpoint": "/eps-history",
        "type": "chart",
        "w": 20,
        "h": 9,
        "raw": true,
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ]
      }
    }
  }
}

{
  "done": false,
  "tool": "manage_apps",
  "args": {
    "backend_id": "backend_001",
    "dashboard_name": "Earnings Sync Live Board",
    "operation": "instantiate",
    "template_id": "Earnings Sync Live",
    "apps_json": [
      {
        "name": "Earnings Sync Live",
        "description": "Live grouped revisions and EPS history.",
        "tabs": {
          "review": {
            "id": "review",
            "name": "Review",
            "layout": [
              {
                "i": "estimate_revisions",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9,
                "state": {
                  "params": {
                    "symbol": "NVDA"
                  }
                }
              }
            ]
          },
          "linked": {
            "id": "linked",
            "name": "Linked",
            "layout": [
              {
                "i": "earnings_chart",
                "x": 0,
                "y": 0,
                "w": 12,
                "h": 9,
                "state": {
                  "params": {
                    "symbol": "NVDA"
                  }
                }
              }
            ],
            "groups": [
              {
                "name": "Live Symbol Sync",
                "type": "param",
                "paramName": "symbol",
                "widgetIds": [
                  "estimate_revisions",
                  "earnings_chart"
                ]
              }
            ]
          }
        }
      }
    ]
  }
}

